// Placeholder for the davidshimjs/qrcodejs library. The invoice layout only calls this when
// a UPI payment QR code is configured (jsonData.config.include_payment_qrcode +
// jsonData.others.upi_id) - not wired up anywhere in this app yet, so this renders a plain
// gray box instead of an actual scannable QR code. Replace with the real qrcode.js build
// (https://github.com/davidshimjs/qrcodejs) if/when payment QR codes are needed.
function QRCode(el, opts) {
    var w = (opts && opts.width) || 100;
    var h = (opts && opts.height) || 100;
    var div = document.createElement('div');
    div.style.width = w + 'px';
    div.style.height = h + 'px';
    div.style.background = '#ccc';
    div.style.display = 'inline-block';
    if (el && el.appendChild) {
        el.insertBefore(div, el.firstChild);
    }
}
